def solve_game(N):
    # DP array: -1 for P-position (Losing), 1 for N-position (Winning)
    # We only need DP up to N-1. Index 0 is unused.
    dp = {} 

    # We iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):

        moves = []

        # Check move n+1
        if n + 1 <= N:
            moves.append(n + 1)

        # Check move 2n
        if 2 * n <= N:
            moves.append(2 * n)


        # Determine if n is a Winning (N) or Losing (P) position

        # Check for immediate win (move to N)
        if N in moves:
            dp[n] = 1 # N-position (Winning)
            continue

        # Standard game theory rules for n < N, where moves are also < N

        can_move_to_L = False

        for m in moves:
            # m < N, so dp[m] should be defined.
            # If dp[m] is -1 (Losing position for the next player), then n is a Winning position.
            if m in dp and dp[m] == -1:
                can_move_to_L = True
                break

        if can_move_to_L:
            dp[n] = 1 # N-position (Winning)
        else:
            # All moves lead to N-positions (Winning for the next player)
            dp[n] = -1 # P-position (Losing)

    # Player A starts at 1. 
    # If dp[1] == 1 (N-position), A wins (Type A).
    # If dp[1] == -1 (P-position), B wins (Type B).
    return dp.get(1)

def find_least_N_type_B(start_N=401):
    print(f"Searching for the least Type B number N > {start_N-1}...")
    N = start_N
    while True:
        result = solve_game(N)

        if result == -1:
            print(f"Found it! N = {N} is Type B (Losing position for the first player A).")
            return N

        if N % 100 == 0:
            print(f"Checked N = {N}. Still Type A.")

        N += 1

