def solve_game(N):
    # Implementation copied from previous step
    if N == 1:
        return 'A'

    status = {}

    for n in range(N - 1, 0, -1):
        can_win = False

        m1 = n + 1
        if m1 <= N:
            if m1 == N:
                can_win = True
            elif not status[m1]:
                can_win = True

        m2 = 2 * n
        if m2 <= N:
            if m2 == N:
                can_win = True
            elif not status[m2]:
                can_win = True

        if not can_win and (n + 1 > N and 2 * n > N):
             status[n] = False
        else:
             status[n] = can_win

    if status[1]:
        return 'A'
    else:
        return 'B'

